data.query:
query Query($whereType:ValidationTypeWhereInput ,$whereModel: DataModelWhereInput, $orderBy: [DataModelOrderByInput!], $first: Int, $after: String) {
  dataModel(where: $whereModel, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        currentDataModelDeployment {
          modelDefinition
          dataModelVersion {
            id number
        }
        }
      }
    }
  },
  validationType(where:$whereType){
    edges {
      node {
        validate
        warn
        fail 
        onCreate
        onUpdate
        onDelete 
      }
    }
  }
}

data.transform:
{
  "LOCAL": {
    "fields": $.dataModel.edges.node.currentDataModelDeployment.modelDefinition.fields.{
      "name": name,
      "type": type,
      "description":description,
      "default": {
        "exists": $isNilOrEmpty(metadata.**.defaultValue) ? false : true,
        "value": $isNilOrEmpty(metadata.**.defaultValue) ? "" : metadata.**.defaultValue
        },
      "unique": metadata.unique,
      "required": $contains(type,"!")
    },
    "dateModelVersion":$.dataModel.edges.node.currentDataModelDeployment.dataModelVersion,
    "validation":$.validationType.edges.node
  }
}

